CELLS = ['%matplotlib inline\nfrom d2l import torch as d2l\nimport math\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F', 'batch_size, num_steps = 32, 35\ntrain_iter, vocab = d2l.load_data_time_machine(batch_size, num_steps)', 'F.one_hot(torch.tensor([0, 2]), len(vocab))', 'X = d2l.reshape(d2l.arange(10), (2, 5))\nF.one_hot(X.T, 28).shape', 'def get_params(vocab_size, num_hiddens, device):\n    num_inputs = num_outputs = vocab_size\n\n    def normal(shape):\n        return torch.randn(size=shape, device=device) * 0.01\n\n    # 隐藏层参数\n    W_xh = normal((num_inputs, num_hiddens))\n    W_hh = normal((num_hiddens, num_hiddens))\n    b_h = d2l.zeros(num_hiddens, device=device)\n    # 输出层参数\n    W_hq = normal((num_hiddens, num_outputs))\n    b_q = d2l.zeros(num_outputs, device=device)\n    # 附加梯度\n    params = [W_xh, W_hh, b_h, W_hq, b_q]\n    for param in params:\n        param.requires_grad_(True)\n    return params', 'def init_rnn_state(batch_size, num_hiddens, device):\n    return (d2l.zeros((batch_size, num_hiddens), device=device), )', 'def rnn(inputs, state, params):\n    # inputs的形状：(时间步数量，批量大小，词表大小)\n    W_xh, W_hh, b_h, W_hq, b_q = params\n    H, = state\n    outputs = []\n    # X的形状：(批量大小，词表大小)\n    for X in inputs:\n        H = torch.tanh(torch.mm(X, W_xh) + torch.mm(H, W_hh) + b_h)\n        Y = torch.mm(H, W_hq) + b_q\n        outputs.append(Y)\n    return torch.cat(outputs, dim=0), (H,)', 'num_hiddens, num_epochs, lr = 64, 150, 1\nnet = d2l.RNNModelScratch(len(vocab), num_hiddens, d2l.try_gpu(), get_params,\n                      init_rnn_state, rnn)\nd2l.train_ch8(net, train_iter, vocab, lr, num_epochs, d2l.try_gpu())', 'net = d2l.RNNModel(nn.RNN(len(vocab), 64), vocab_size=len(vocab))\nd2l.train_ch8(net, train_iter, vocab, 1, 150, d2l.try_gpu())']
